/** Multiple team members selected through the shared checkbox and popover primitives. */
export function BoardAssigneePicker({
  value,
  people,
  onChange,
  creating = false,
}: BoardAssigneePickerProps) {
  if (creating) {
    const selected = value[0];
    const parts = selected?.name.trim().split(/\s+/) ?? [];
    const compactName = parts.length > 1 ? `${parts[0]} ${parts.at(-1)?.[0]}.` : selected?.name;
    return (
      <Select
        aria-label="Assignee"
        selectedKey={selected?.name ?? null}
        isDisabled={!people.length}
        onSelectionChange={(key) => {
          const person = people.find((person) => person.name === key);
          onChange(person ? [person] : []);
        }}
        triggerClassName="w-auto min-w-0 justify-start gap-1.5 rounded-md border-0 bg-transparent p-0 text-body-medium text-text-secondary shadow-none hover:bg-background-primary-hover [&>svg]:hidden"
        popoverClassName="w-[220px] rounded-[14px] p-1"
        renderValue={() => (
          <span className="flex min-w-0 items-center gap-1.5">
            {selected ? (
              <>
                <Avatar
                  size="sm"
                  className="size-[18px]"
                  initials={selected.initials}
                  src={selected.src}
                  alt=""
                  aria-hidden
                />
                {compactName}
              </>
            ) : (
              <>
                <BoardFieldIcon kind="assignee" />
                <span className="text-text-tertiary">Assignee</span>
              </>
            )}
          </span>
        )}
      >
        {people.map((person) => (
          <SelectItem id={person.name} key={person.name} textValue={person.name} className="px-2 py-1.5">
            <Avatar
              size="sm"
              className="size-[18px]"
              initials={person.initials}
              src={person.src}
              alt=""
              aria-hidden
            />
            {person.name}
          </SelectItem>
        ))}
      </Select>
    );
  }
  return (
    <Dropdown>
      <DropdownTrigger
        aria-label={creating ? "Assignee" : "Edit assignees"}
        className={`flex min-w-0 items-center gap-1.5 rounded-md -m-1 p-1 text-body-medium outline-none hover:bg-background-primary-hover`}
