"use client";
import { useState } from "react";
import { DEFAULT_BOARD_VIEW, type BoardSort, type BoardViewOptions } from "./board-toolbar";
import type { ProjectBoardColumnData, ProjectBoardTask } from "./project-board";

const priorityRank = { Urgent: 0, High: 1, Medium: 2, Low: 3 };
function sortTasks(tasks: ProjectBoardTask[], sort: BoardSort) {
  return tasks.toSorted((a, b) =>
    sort === "title"
      ? a.title.localeCompare(b.title)
      : sort === "priority"
        ? priorityRank[a.priority] - priorityRank[b.priority]
        : 0,
  );
}

/** Keep the working row order independent of the host's task objects. */
export function useBoardView(columns: ProjectBoardColumnData[]) {
  const [view, setView] = useState(DEFAULT_BOARD_VIEW);
  const [order, setOrder] = useState<readonly string[]>([]);
  const ranks = new Map(order.map((id, index) => [id, index]));
  const orderedColumns = columns.map((column) => ({
    ...column,
    tasks: sortTasks(
      column.tasks.toSorted(
        (a, b) => (ranks.get(a.id) ?? order.length) - (ranks.get(b.id) ?? order.length),
      ),
      view.sort,
    ),
  }));
  const changeView = (next: BoardViewOptions) => {
    if (next.sort !== view.sort) {
      setOrder(
        orderedColumns.flatMap((column) =>
          sortTasks(column.tasks, next.sort).map((task) => task.id),
        ),
      );
    }
    setView(next);
  };
  const displayed = orderedColumns
    .filter((column) => view.showDone || column.id !== "done")
    .map((column) => ({
      ...column,
      tasks: column.tasks.filter(
        (task) =>
          (view.priority === "all" || task.priority === view.priority) &&
          (view.project === "all" || task.project === view.project),
      ),
    }));
  const moveTask = (taskId: string, columnId: string, index: number) => {
    const task = columns.flatMap((column) => column.tasks).find((task) => task.id === taskId);
    if (!task) return null;
    const next = orderedColumns.map((column) => {
      const tasks = column.tasks.filter((task) => task.id !== taskId);
      if (column.id === columnId) {
        const visibleTarget = displayed.find((column) => column.id === columnId)?.tasks
          .filter((task) => task.id !== taskId)[index];
        const position = visibleTarget ? tasks.findIndex((task) => task.id === visibleTarget.id) : tasks.length;
        tasks.splice(position, 0, task);
      }
      return { ...column, tasks };
    });
    setOrder(next.flatMap((column) => column.tasks.map((task) => task.id)));
    return next;
  };
  return { view, changeView, displayed, moveTask };
}

