/** Measured sortable layout transition; direct pointer movement does not interpolate. */
export const BOARD_REORDER_TRANSITION = { duration: 0.26, ease: [0.22, 1, 0.36, 1] } as const;
interface BoardDrag {
  task: ProjectBoardTask;
  x: number;
  y: number;
  startX: number;
  startY: number;
  left: number;
  top: number;
  width: number;
  height: number;
}
export function ProjectBoard({
  columns,
  onOpen,
  onAdd,
  onTaskMove,
  fill = true,
}: {
  columns: ProjectBoardColumnData[];
  onOpen?: (task: ProjectBoardTask) => void;
  onAdd?: (column: string) => void;
  onTaskMove?: (taskId: string, columnId: string, index: number) => void;
  fill?: boolean;
}) {
  const root = useRef<HTMLDivElement>(null),
    pending = useRef<BoardDrag | null>(null),
    active = useRef(false),
    suppressClick = useRef(false),
    cancelled = useRef(false),
    moveRef = useRef(onTaskMove),
    focusTask = useRef<string | null>(null);
  const [drag, setDrag] = useState<BoardDrag | null>(null),
    [keyboard, setKeyboard] = useState<{
      task: ProjectBoardTask;
      column: number;
      index: number;
    } | null>(null),
    [announcement, setAnnouncement] = useState("");
  const reduced = useReducedMotion();
  moveRef.current = onTaskMove;
  useEffect(() => {
    if (focusTask.current) {
      const target = [
        ...(root.current?.querySelectorAll<HTMLElement>("[data-board-task]") ?? []),
      ].find((el) => el.dataset.boardTask === focusTask.current);
      target?.focus();
      focusTask.current = null;
    }
  }, [columns]);
  useEffect(() => {
    const move = (e: PointerEvent) => {
      const item = pending.current;
      if (!item) return;
      if (!active.current && Math.hypot(e.clientX - item.startX, e.clientY - item.startY) < 6)
        return;
      active.current = true;
      item.x = e.clientX;
      item.y = e.clientY;
      setDrag({ ...item });
      e.preventDefault();
    };
    const end = (e: PointerEvent) => {
      if (cancelled.current) {
        cancelled.current = false;
        suppressClick.current = true;
        setTimeout(() => {
          suppressClick.current = false;
        }, 0);
        return;
      }
      const item = pending.current;
      pending.current = null;
      if (!item || !active.current) return;
      active.current = false;
      suppressClick.current = true;
      setTimeout(() => {
        suppressClick.current = false;
      }, 0);
      const hit = document.elementFromPoint(e.clientX, e.clientY);
      const column = hit?.closest<HTMLElement>("[data-board-column]");
      if (column && root.current?.contains(column)) {
        const cards = [...column.querySelectorAll<HTMLElement>("[data-board-task]")].filter(
          (c) => c.dataset.boardTask !== item.task.id,
        );
        let index = cards.findIndex(
          (card) =>
            e.clientY <
            card.getBoundingClientRect().top + card.getBoundingClientRect().height / 2 + 1,
        );
        if (index < 0) index = cards.length;
        moveRef.current?.(item.task.id, column.dataset.boardColumn!, index);
        setAnnouncement(`${item.task.id} moved to ${column.getAttribute("aria-label")}.`);
      }
      setDrag(null);
    };
    const cancel = () => {
      pending.current = null;
      active.current = false;
      setDrag(null);
    };
    const escape = (e: KeyboardEvent) => {
      if (e.key === "Escape" && active.current) {
        e.preventDefault();
        cancelled.current = true;
        cancel();
        setAnnouncement("Move cancelled.");
      }
    };
    const touch = (e: TouchEvent) => {
      if (active.current) e.preventDefault();
    };
    window.addEventListener("keydown", escape);
    window.addEventListener("pointermove", move, { passive: false });
    window.addEventListener("pointerup", end);
    window.addEventListener("pointercancel", cancel);
    window.addEventListener("touchmove", touch, { passive: false });
    return () => {
      window.removeEventListener("keydown", escape);
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", end);
      window.removeEventListener("pointercancel", cancel);
      window.removeEventListener("touchmove", touch);
    };
  }, []);
  const start = (task: ProjectBoardTask, e: ReactPointerEvent<HTMLButtonElement>) => {
    if (!onTaskMove || e.button !== 0) return;
    const r = e.currentTarget.getBoundingClientRect();
    pending.current = {
      task,
      x: e.clientX,
      y: e.clientY,
      startX: e.clientX,
      startY: e.clientY,
      left: r.left,
      top: r.top,
      width: r.width,
      height: r.height,
    };
  };
  const key = (task: ProjectBoardTask, e: ReactKeyboardEvent<HTMLButtonElement>) => {
    if (!onTaskMove) return;
    if (!keyboard && e.key === " ") {
      e.preventDefault();
      setKeyboard({
        task,
        column: columns.findIndex((c) => c.tasks.some((t) => t.id === task.id)),
        index: 0,
      });
      setAnnouncement(
        `Picked up ${task.id}. Use arrow keys to choose a position, Space to drop, Escape to cancel.`,
      );
      return;
    }
    if (!keyboard) return;
    if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", " ", "Enter", "Escape"].includes(e.key))
      e.preventDefault();
    if (e.key === "Escape") {
      setKeyboard(null);
      setAnnouncement("Move cancelled.");
    } else if (e.key === " " || e.key === "Enter") {
      focusTask.current = keyboard.task.id;
      onTaskMove(keyboard.task.id, columns[keyboard.column].id, keyboard.index);
      setAnnouncement(`${keyboard.task.id} moved to ${columns[keyboard.column].title}.`);
      setKeyboard(null);
    } else if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      const column = Math.max(
        0,
        Math.min(columns.length - 1, keyboard.column + (e.key === "ArrowRight" ? 1 : -1)),
      );
      setKeyboard({ ...keyboard, column, index: 0 });
      setAnnouncement(`${columns[column].title}, first position.`);
      [...(root.current?.querySelectorAll<HTMLElement>("[data-board-column]") ?? [])]
        .find((el) => el.dataset.boardColumn === columns[column].id)
        ?.scrollIntoView?.({
          block: "nearest",
          inline: "nearest",
          behavior: reduced ? "instant" : "smooth",
        });
    } else if (e.key === "ArrowUp" || e.key === "ArrowDown") {
      const index = Math.max(
        0,
        Math.min(
          columns[keyboard.column].tasks.length,
          keyboard.index + (e.key === "ArrowDown" ? 1 : -1),
        ),
      );
      setKeyboard({ ...keyboard, index });
      setAnnouncement(`Position ${index + 1}.`);
    }
  };
  return (
    <div
      ref={root}
      role="region"
      aria-label="Project board columns"
      tabIndex={0}
      onDragStart={(e) => e.preventDefault()}
      onClickCapture={(e) => {
        if (suppressClick.current) {
          e.preventDefault();
          e.stopPropagation();
        }
      }}
      className="-mx-3 min-h-0 flex-1 overflow-x-auto overflow-y-hidden overscroll-x-contain [scrollbar-width:thin] sm:-mx-6 lg:-me-7"
    >
      <span role="status" aria-live="polite" className="sr-only">
        {announcement}
      </span>
      <div
        className={cx(
          "grid h-full w-max grid-flow-col auto-cols-[273px] gap-2 px-3 sm:px-6 lg:pe-7",
          fill && "min-[1441px]:auto-cols-[minmax(273px,1fr)] min-[1441px]:w-[max(100%,1449px)]",
        )}
      >
        {columns.map((c) => (
          <BoardColumn
            key={c.id}
            column={c}
            onOpen={onOpen}
            onAdd={() => onAdd?.(c.id)}
            dragTaskId={drag?.task.id}
            onTaskPointerDown={start}
            onTaskKeyDown={key}
          />
        ))}
      </div>
      {drag &&
        createPortal(
          <div
            aria-hidden="true"
            className="pointer-events-none fixed z-50 cursor-grabbing"
            style={{
              left: drag.left,
              top: drag.top,
              width: drag.width,
              height: drag.height,
              transform: `translate3d(${drag.x - drag.startX}px,${drag.y - drag.startY}px,0)`,
            }}
          >
            <BoardTaskCard task={drag.task} interactive={false} />
          </div>,
          document.body,
        )}
    </div>
  );
}

// @zeus-internal
export function boardTicketFragment(id: string) {
  return `#ticket=ticket-${encodeURIComponent(id.toLowerCase())}`;
}
export function boardTicketIdFromFragment(hash: string, ids: readonly string[]) {
  try {
    const match = hash.startsWith("#ticket=ticket-")
      ? decodeURIComponent(hash.slice("#ticket=ticket-".length))
      : hash.startsWith("#ticket-") ? decodeURIComponent(hash.slice("#ticket-".length)) : null;
    return ids.find((id) => id.toLowerCase() === match?.toLowerCase()) ?? null;
  } catch { return null; }
}

