"use client";
import { RiAddLine, RiInbox2Line, RiKanbanView2 } from "@remixicon/react";
import { useEffect, useState } from "react";
import { Button } from "../../base/buttons/button";
import { IconButton } from "../../base/buttons/icon-button";
import { DASHBOARD_NAV } from "../dashboard/dashboard-sidebar";
import { NotificationBell } from "../app-shell/notification-bell";
import { STARTER_NOTIFICATIONS } from "../app-shell/starter-notifications";
import {
  ProjectBoard,
  type ProjectBoardColumnData,
  type ProjectBoardTask,
} from "../project-board/project-board";
import { BoardToolbar } from "../project-board/board-toolbar";
import { boardTicketIdFromFragment } from "../project-board/ticket-link";
import { useBoardView } from "../project-board/board-view";
import { BoardTicketComposer, type BoardTicketDraft } from "../project-board/board-ticket-composer";
import { BoardTaskDrawer } from "../project-board/board-task-drawer";
import type { BoardPerson } from "../project-board/board-properties";
import { DEFAULT_PROJECT_COLUMNS, DEFAULT_PROJECT_PEOPLE } from "./project-board-data";
import { TemplateShell, type TemplateShellProps } from "./template-shell";
export interface ProjectBoardTemplateProps
  extends Pick<
    TemplateShellProps,
    "account" | "accounts" | "team" | "navigationItems" | "contained" | "className"
  > {
  title?: string;
  columns?: ProjectBoardColumnData[];
  onColumnsChange?: (columns: ProjectBoardColumnData[]) => void;
  people?: BoardPerson[];
  /** Project directory; inferred choices retain their order as tickets move. */
  projects?: readonly string[];
  commentAuthor?: BoardPerson;
}
export function ProjectBoardTemplate({
  title = "Workspace Design Tasks",
  columns: suppliedColumns,
  onColumnsChange,
  people: suppliedPeople,
  projects: suppliedProjects,
  commentAuthor,
  ...shell
}: ProjectBoardTemplateProps = {}) {
  const [localColumns, setColumns] = useState(DEFAULT_PROJECT_COLUMNS),
    [openedId, setOpenedId] = useState<string | null>(null),
    [creating, setCreating] = useState(false),
    [initialStatus, setInitialStatus] = useState<string | undefined>(),
    [creationKey, setCreationKey] = useState(0);
  const columns = suppliedColumns ?? localColumns;
  const { view, changeView, displayed, moveTask } = useBoardView(columns);
  const tasks = columns.flatMap((c) => c.tasks),
    opened = tasks.find((t) => t.id === openedId) ?? null;
  const people =
    suppliedPeople ??
    (suppliedColumns
      ? [...new Map(tasks.flatMap((t) => t.assignees ?? []).map((p) => [p.name, p])).values()]
      : DEFAULT_PROJECT_PEOPLE);
  const detectedProjects = [...new Set(tasks.map((task) => task.project))];
  const [projectDirectory, setProjectDirectory] = useState(detectedProjects);
  const newProjects = detectedProjects.filter((project) => !projectDirectory.includes(project));
  if (newProjects.length) setProjectDirectory([...projectDirectory, ...newProjects]);
  const projects = suppliedProjects ?? (projectDirectory.length ? projectDirectory : ["Workspace"]);
  const taskIds = tasks.map((task) => task.id).join("\0");
  useEffect(() => {
    const read = () => {
      const id = boardTicketIdFromFragment(window.location.hash, taskIds.split("\0"));
      if (id) setOpenedId(id);
    };
    read();
    window.addEventListener("hashchange", read);
    return () => window.removeEventListener("hashchange", read);
  }, [taskIds]);
  const closeTicket = () => setOpenedId(null);
  const update = (next: ProjectBoardColumnData[]) => {
    if (!suppliedColumns) setColumns(next);
    onColumnsChange?.(next);
  };
  const updateTask = (task: ProjectBoardTask, columnId: string) => {
    const previous = columns.find((c) => c.tasks.some((t) => t.id === task.id));
    update(
      columns.map((c) => ({
        ...c,
        tasks:
          c.id === previous?.id && c.id === columnId
            ? c.tasks.map((t) => (t.id === task.id ? task : t))
            : [...c.tasks.filter((t) => t.id !== task.id), ...(c.id === columnId ? [task] : [])],
      })),
    );
  };
  const begin = (column?: string) => {
    setInitialStatus(column);
    setCreationKey((k) => k + 1);
    setCreating(true);
  };
  let number = 90;
  while (tasks.some((t) => t.id === `FE-${number}`)) number++;
  const ticketId = `FE-${number}`;
  const create = (draft: BoardTicketDraft) => {
    const task: ProjectBoardTask = {
      id: ticketId,
      group: draft.title,
      title: draft.title,
      date: "Since today",
      priority: draft.priority,
      project: draft.project,
      assignees: draft.assignees,
      description: draft.description,
      creator: commentAuthor ?? people[0],
      comments: [],
    };
    update(columns.map((c) => (c.id === draft.status ? { ...c, tasks: [...c.tasks, task] } : c)));
  };
  return (
    <>
      <TemplateShell
        {...shell}
        navigationItems={shell.navigationItems ?? DASHBOARD_NAV}
        headerClassName="shrink-0 gap-2 sm:gap-0"
        selected="project-board"
        title="Project board"
        heading={title}
        icon={RiKanbanView2}
        className={`lg:h-dvh lg:min-h-0 ${shell.className ?? ""}`}
        frameClassName="overflow-hidden sm:px-6 sm:pb-[22px] lg:overflow-hidden lg:pe-7"
        columnClassName="min-h-0 flex-1 max-w-none"
        actions={
          <>
            <NotificationBell
              notifications={STARTER_NOTIFICATIONS.slice(0, 5).map((n) => ({ ...n, unread: true }))}
            />
            <IconButton icon={RiInbox2Line} aria-label="Open project inbox" />
            <BoardToolbar value={view} onChange={changeView} projects={projects} />
            <Button leadingIcon={RiAddLine} onClick={() => begin()}>
              New ticket
            </Button>
          </>
        }
      >
        <ProjectBoard
          columns={displayed}
          fill={view.fill}
          onOpen={(task) => setOpenedId(task.id)}
          onAdd={begin}
          onTaskMove={(taskId, columnId, index) => {
            const next = moveTask(taskId, columnId, index);
            if (next) update(next);
          }}
        />
      </TemplateShell>
      <BoardTicketComposer
        key={creationKey}
        isOpen={creating}
        onOpenChange={setCreating}
        boardTitle={title}
        ticketId={ticketId}
        columns={columns}
        projects={projects}
        people={people}
        initialStatus={initialStatus}
        onCreate={create}
      />
      <BoardTaskDrawer
        task={opened}
        onClose={closeTicket}
        boardTitle={title}
        columns={columns}
        projects={projects}
        people={people}
        onUpdate={updateTask}
        commentAuthor={commentAuthor}
      />
    </>
  );
}

