    index = Math.min(bands.length - 1, Math.floor(v * bands.length));
  const [a, b, d, q, x, y] = bands[index]![frame]!,
    localY = v * profile.height - (index * profile.height) / bands.length,
    localX = u * profile.width,
    denominator = q! * localY + 1;
