}
/** Reconstruct a continuous warp from the observed local quads, including their fixed offscreen origin. */
function fittedPoint(
  width: number,
  height: number,
  direction: GenieDirection,
  frame: number,
  u: number,
  v: number,
): Point {
  const [a, b, c] = GENIE_OBSERVATIONS,
    pa = point(a!, direction, frame, u, v),
    pb = point(b!, direction, frame, u, v),
    pc = point(c!, direction, frame, u, v);
