    const heightFactor = (pb[key] - pa[key]) / (b!.height - a!.height),
      widthFactor =
        (pc[key] - pa[key] - heightFactor * (c!.height - a!.height)) / (c!.width - a!.width);
    return pa[key] + widthFactor * (width - a!.width) + heightFactor * (height - a!.height);
