}
export function genieMotion(width: number, height: number, direction: GenieDirection) {
  const profile = GENIE_OBSERVATIONS.reduce(
    (best, item) =>
      Math.abs(item.width - width) * 4 + Math.abs(item.height - height) <
      Math.abs(best.width - width) * 4 + Math.abs(best.height - height)
        ? item
