    width === profile.width && height === profile.height
      ? pose.bands.map((frames) =>
          frames.map((values) => ({
            transform: matrix(values, width / profile.width, height / profile.height),
          })),
        )
      : Array.from({ length: count }, (_, index) => {
          const geometry = genieRowGeometry(profile, height, index, count),
            top = geometry.offset / height,
            bottom = (geometry.offset + geometry.height) / height;
