                : quadMatrix(
                    fittedPoint(width, height, direction, frame, 0, top),
                    fittedPoint(width, height, direction, frame, 1, top),
                    fittedPoint(width, height, direction, frame, 1, bottom),
                    fittedPoint(width, height, direction, frame, 0, bottom),
                    width,
                    geometry.height,
