import { SQUEEZE_OBSERVATIONS } from "./squeeze-motion-data";
import type { GenieDirection } from "./genie-types";
export function squeezePose(
  width: number,
  height: number,
  time: number,
  direction: GenieDirection,
) {
  const profile = SQUEEZE_OBSERVATIONS.reduce(
    (best, item) =>
      Math.abs(item.width - width) * 4 + Math.abs(item.height - height) <
      Math.abs(best.width - width) * 4 + Math.abs(best.height - height)
        ? item
        : best,
    SQUEEZE_OBSERVATIONS[0]!,
  );
  const rows = profile[direction],
    t = Math.max(0, Math.min(480, time + profile.observationFrameMs));
  let index = 1;
  while (index < rows.length - 1 && rows[index]![0]! < t) index++;
  const from = rows[index - 1]!,
    to = rows[index]!,
    fraction = (t - from[0]!) / Math.max(0.0001, to[0]! - from[0]!);
  const values = from.map((value, i) => value + (to[i]! - value) * fraction);
