    transform: `translateY(${translate}px) scaleY(${scale})`,
    opacity: values[3]!,
    displacement: values[4]! * width,
    blur: values[5]!,
    shadowTransform: `translateY(${values[8]! * 64}px) scale(${values[6]}, ${values[7]})`,
    shadowOpacity: values[9]!,
  };
}
/** A smooth horizontal displacement field whose influence increases cubically toward the lower edge. */
export function squeezeField(width: number) {
  const sigmoid = (x: number) => 1 / (1 + Math.exp(-32 * (x - 0.5))),
    minimum = sigmoid(0),
    span = sigmoid(1) - minimum;
