  const red = positions
    .map(
      (t) =>
        `<stop offset="${t}" stop-color="rgb(${(255 * (sigmoid(t) - minimum)) / span},128,128)"/>`,
    )
    .join("");
  const alpha = positions
    .map((t) => `<stop offset="${t}" stop-color="white" stop-opacity="${t * t * t}"/>`)
    .join("");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="280" viewBox="0 0 ${width} 280"><defs><linearGradient id="horizontal">${red}</linearGradient><linearGradient id="vertical" x1="0" y1="0" x2="0" y2="1">${alpha}</linearGradient><mask id="influence"><rect width="${width}" height="280" fill="url(#vertical)"/></mask></defs><rect width="${width}" height="280" fill="rgb(128,128,128)"/><rect width="${width}" height="280" fill="url(#horizontal)" mask="url(#influence)"/></svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

