              result="horizontal-field"
            />
            <feComposite
              in="horizontal-field"
              in2="neutral"
              operator="over"
              result="displacement-field"
            />
            <feDisplacementMap
              ref={displacement}
              in="SourceGraphic"
              in2="displacement-field"
              scale="0"
              xChannelSelector="R"
              yChannelSelector="G"
            />
            <feGaussianBlur ref={blur} stdDeviation="0" />
          </filter>
        </defs>
      </svg>
      <div
        ref={shadow}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 opacity-0"
        style={{ transformOrigin: "center bottom" }}
      />
      <div data-squeeze-surface="" ref={surface} style={{ transformOrigin: "center bottom" }}>
        {children}
      </div>
    </div>
  );
}

